/*
 * Service worker for Caro Calculator.
 *
 * Two jobs:
 *   1. Make the app installable — browsers require a service worker with a
 *      fetch handler before they will offer "Add to home screen".
 *   2. Make it work with no signal. Restaurant basements have terrible
 *      reception, and "I'll assign" mode needs no network at all — so the app
 *      shell should open whether or not there is internet.
 *
 * Written by hand rather than generated by a build plugin, because a plugin
 * would be a dependency and this is forty lines. It never precaches a list of
 * hashed filenames (which it could not know); it caches what it is asked for
 * as it goes.
 */

const CACHE = 'caro-v1'

self.addEventListener('install', () => {
  // Take over immediately rather than waiting for every tab to close.
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Drop caches from older versions of this worker.
      const names = await caches.keys()
      await Promise.all(names.filter((n) => n !== CACHE).map((n) => caches.delete(n)))
      await self.clients.claim()
    })(),
  )
})

self.addEventListener('fetch', (event) => {
  const { request } = event
  if (request.method !== 'GET') return

  const url = new URL(request.url)
  // Never touch Firestore traffic — it has its own offline handling, and
  // caching live bill data here would serve people stale claims.
  if (url.origin !== self.location.origin) return

  // Navigations: network first, so a deploy is picked up on the next visit
  // rather than being pinned to a stale index.html.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone()
          caches.open(CACHE).then((cache) => cache.put(request, copy))
          return response
        })
        .catch(async () => (await caches.match(request)) ?? caches.match('./')),
    )
    return
  }

  // Everything else (hashed JS/CSS, icons): cache first. Filenames change on
  // every build, so a cached asset is never the wrong version.
  event.respondWith(
    caches.match(request).then(
      (cached) =>
        cached ??
        fetch(request).then((response) => {
          if (response.ok) {
            const copy = response.clone()
            caches.open(CACHE).then((cache) => cache.put(request, copy))
          }
          return response
        }),
    ),
  )
})
